using System;
using System.Collections;
using Astrea.BattleActions;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using TMPro;
using UnityEngine;

namespace Astrea;

public class CompanionInitializer : MonoBehaviour
{
	[Header("Companion Upgrade")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[Header("Components To Initialize")]
	[SerializeField]
	private CompanionCorruptionStats companionCorruptionStats;

	[SerializeField]
	private CompanionSpriteControl companionSpriteControl;

	[SerializeField]
	private CompanionEffects companionEffects;

	[SerializeField]
	private bool companionForBattle;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionAbility companionAbility;

	[SerializeField]
	private TextMeshProUGUI companionLevelText;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject corruptionGaugeLevelAndEffects;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private UnitFeedbackHandler unitFeedbackHandler;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionSFXData companionSFXData;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private TooltipNameInstance tooltipNameInstance;

	[Header("Fainted Companion")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private TargetInstance companionFaintedTargetInstance;

	[Header("VFX")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject sentinelPowerUpVFXPrefab;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject sentinelRepairEndOfBattleVFXPrefab;

	[Header("Achievements")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private AchievementData loyalPartnerAchievementData;

	[Header("Events")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private VoidEvent OnAfterRewardFadeInCanvasAndUpdateEventsPanel;

	[Header("SFX")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private EventReference sentinelUpgradeSFX;

	[Header("Repair After Few Turns")]
	[SerializeField]
	[ShowIf("companionForBattle")]
	private RepairAction repairAction;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private SentinelAutoRepairHUD sentinelAutoRepairHUD;

	private RuntimeCompanion runtimeCompanion;

	[SerializeField]
	private int positioningIndex;

	private StartingEffect startingEffectToAdd;

	public CompanionSpriteControl CompanionSpriteControl => companionSpriteControl;

	public UnitFeedbackHandler UnitFeedbackHandler => unitFeedbackHandler;

	public CompanionSFXData CompanionSFXData => companionSFXData;

	public TargetInstance CompanionFaintedTargetInstance => companionFaintedTargetInstance;

	public SentinelAutoRepairHUD SentinelAutoRepairHUD => sentinelAutoRepairHUD;

	public RuntimeCompanion RuntimeCompanion => runtimeCompanion;

	public CompanionData CompanionData => runtimeCompanion.CompanionData;

	public int CompanionLevel => runtimeCompanion.CompanionLevel;

	public int PositioningIndex => positioningIndex;

	public void InitializeCompanionEntirely(RuntimeCompanion runtimeCompanion, bool isPreviewCompanion = false)
	{
		InitializeCompanionEntirely(runtimeCompanion, positioningIndex, effectFeedback: true, isPreviewCompanion);
	}

	public void InitializeCompanionEntirely(RuntimeCompanion runtimeCompanion, int positioningIndex, bool effectFeedback, bool isPreviewCompanion = false)
	{
		InitializeCompanionWithoutEffects(runtimeCompanion, positioningIndex);
		InitializeCompanionEffects(effectFeedback, isPreviewCompanion);
	}

	public void InitializeCompanionEntirelyWithoutStoreDiceRecycle(RuntimeCompanion runtimeCompanion)
	{
		InitializeCompanionWithoutCompanionAbility(runtimeCompanion, positioningIndex, repair: false);
		InitializeCompanionEffects(effectFeedback: true);
		companionAbility.InitializeWithoutStoreDice(CompanionData.GetCompanionLevels()[CompanionLevel].CompanionDice, tryStoreBoostedDice: true);
	}

	public void InitializeCompanionWithoutEffects(RuntimeCompanion runtimeCompanion, int positioningIndex)
	{
		InitializeCompanionWithoutCompanionAbility(runtimeCompanion, positioningIndex, repair: false);
		if (companionForBattle)
		{
			companionAbility.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].CompanionDice);
			sentinelAutoRepairHUD.ResetSentinelBrokenTurnsCounter();
		}
	}

	private void InitializeCompanionWithoutCompanionAbility(RuntimeCompanion runtimeCompanion, int positioningIndex, bool repair, bool startOfTurnRepair = false)
	{
		this.positioningIndex = positioningIndex;
		this.runtimeCompanion = runtimeCompanion;
		if (companionForBattle)
		{
			corruptionGaugeLevelAndEffects.SetActive(value: true);
		}
		companionLevelText.SetText("{0}", CompanionLevel + 1);
		companionCorruptionStats.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].MaxCorruption, 0);
		if (companionForBattle)
		{
			tooltipNameInstance.Initialize(runtimeCompanion.CompanionData.GetLocalizedCompanionName());
		}
		if (repair)
		{
			if (!startOfTurnRepair)
			{
				companionSpriteControl.InitializeRepairBrokenCompanion();
			}
		}
		else
		{
			companionSpriteControl.Initialize(CompanionData);
		}
	}

	public void InitializeCompanionEffects(bool effectFeedback, bool isPreviewCompanion = false)
	{
		companionEffects.Initialize(runtimeCompanion, effectFeedback, isPreviewCompanion);
	}

	public void RemoveAllCompanionEffectsWithCallbacks()
	{
		companionEffects.RemoveAllEffectsWithCallbacks();
	}

	public void EndOfBattleInitialize()
	{
		sentinelAutoRepairHUD.ResetSentinelBrokenTurnsCounter();
		if (companionCorruptionStats.IsDefeated())
		{
			if (companionForBattle)
			{
				corruptionGaugeLevelAndEffects.SetActive(value: true);
			}
			companionSpriteControl.EndOfBattleInitializeBrokenCompanion();
			companionEffects.ResetPreviousEffectsVariables();
			InitializeCompanionEffects(effectFeedback: false);
			ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(sentinelRepairEndOfBattleVFXPrefab, base.transform.position, 5f);
		}
		else
		{
			companionEffects.EndOfBattleInitializeAliveCompanion(runtimeCompanion.GetCombinedEffects());
		}
		companionCorruptionStats.EndOfBattleInitialize();
		companionAbility.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].CompanionDice);
	}

	public void InitializeCompanionEntirelyRepairAction(bool startOfTurnRepair)
	{
		sentinelAutoRepairHUD.ResetSentinelBrokenTurnsCounter();
		InitializeCompanionWithoutCompanionAbility(runtimeCompanion, positioningIndex, repair: true, startOfTurnRepair);
		companionAbility.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].CompanionDice);
		InitializeCompanionEffects(effectFeedback: true);
	}

	public void InitializeCompanionNoSpriteControl(RuntimeCompanion runtimeCompanion, bool isPreviewCompanion = false)
	{
		this.runtimeCompanion = runtimeCompanion;
		companionLevelText.SetText("{0}", CompanionLevel + 1);
		companionCorruptionStats.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].MaxCorruption, 0);
		companionEffects.Initialize(runtimeCompanion, effectFeedback: true, isPreviewCompanion);
	}

	public void MaxUpgradeCompanion()
	{
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		StartCoroutine(UpgradeCompanionCoroutine(maxLevelUpgrade: true, 0, delegate
		{
			OnAfterRewardFadeInCanvasAndUpdateEventsPanel.Raise();
			currentCompanions.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
		}));
	}

	public void UpgradeCompanion(Action afterUpgradeAction)
	{
		StartCoroutine(UpgradeCompanionCoroutine(maxLevelUpgrade: false, 1, afterUpgradeAction));
	}

	private IEnumerator UpgradeCompanionCoroutine(bool maxLevelUpgrade, int levelUpAmount, Action afterUpgradeAction)
	{
		int val = CompanionLevel + levelUpAmount;
		val = Math.Min(4, val);
		if (maxLevelUpgrade)
		{
			val = 4;
		}
		runtimeCompanion.UpdateStartingEffectsCompanionUpgraded(val);
		runtimeCompanion.SetCompanionLevel(val);
		yield return new WaitForSeconds(0.5f);
		UpdateUpgradedCompanion();
		yield return StartCoroutine(PowerUpFeedbackCoroutine());
		afterUpgradeAction();
	}

	public IEnumerator PowerUpFeedbackCoroutine(bool playSentinelUpgrade = true)
	{
		if (playSentinelUpgrade)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(sentinelUpgradeSFX);
		}
		VFXHandler vfxInstance = ReferenceSingleton<VFXHandler>.Instance;
		companionSpriteControl.OnBlink();
		vfxInstance.GetVFX(sentinelPowerUpVFXPrefab, base.gameObject.transform.position, 3f);
		yield return new WaitUntil(() => unitFeedbackHandler.SpawnFeedbackCoroutine == null);
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
		{
			yield return new WaitForSeconds(0.8f);
			if (vfxInstance.IsVFXEnabled())
			{
				yield return new WaitForSeconds(0.7f);
			}
		}
		else
		{
			yield return new WaitForSeconds(0.4f);
		}
	}

	public void UpdateUpgradedCompanion()
	{
		if (CompanionLevel == 4)
		{
			loyalPartnerAchievementData.Unlock();
		}
		companionAbility.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].CompanionDice);
		companionLevelText.SetText("{0}", CompanionLevel + 1);
		companionCorruptionStats.Initialize(CompanionData.GetCompanionLevels()[CompanionLevel].MaxCorruption, 0);
		companionEffects.UpdateUpgradedCompanionEffects(runtimeCompanion.GetCombinedEffects());
	}

	public void UpgradeCompanionXTimes(int upgradeAmount)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		StartCoroutine(UpgradeCompanionCoroutine(maxLevelUpgrade: false, upgradeAmount, delegate
		{
			ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
			currentCompanions.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
		}));
	}

	public void OnChooseCompanionToAddStartingEffect(StartingEffect startingEffectToAdd)
	{
		this.startingEffectToAdd = startingEffectToAdd;
	}

	public void CompanionChosenToAddStartingEffect()
	{
		StartCoroutine(CompanionChosenToAddStartingEffectCoroutine());
	}

	private IEnumerator CompanionChosenToAddStartingEffectCoroutine()
	{
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		runtimeCompanion.AddStartingEffect(startingEffectToAdd);
		companionEffects.AddEffect(startingEffectToAdd.Effect, startingEffectToAdd.EffectAmount);
		yield return StartCoroutine(PowerUpFeedbackCoroutine());
		OnAfterRewardFadeInCanvasAndUpdateEventsPanel.Raise();
	}

	public bool CheckSentinelBrokenTurnsCounter()
	{
		if (sentinelAutoRepairHUD.CheckSentinelBrokenTurnsCounter())
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, sentinelAutoRepairHUD.DelayToRepairSentinel, delegate
			{
				companionSpriteControl.EndOfBattleInitializeBrokenCompanion();
				ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(sentinelRepairEndOfBattleVFXPrefab, base.transform.position, 5f);
				repairAction.InitializeCompanion(companionFaintedTargetInstance.gameObject, initializeCompanionEntirely: true, -1, startOfTurnRepair: true);
				InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
				{
					companionEffects.CheckBoostStartOfTurnRepair();
				});
			});
			return true;
		}
		return false;
	}
}
